382	export async function applyFreeMinecraftPreset(_prev: unknown, formData: FormData): Promise<Result> {
383	  const user = await requireUser();
384	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
385	  if (!row) return { error: "You don't have a free server." };
386	
387	  const presetKey = String(formData.get("preset") ?? "");
388	  const preset = FREEMC_PRESETS[presetKey];
389	  if (!preset) return { error: "Unknown preset." };
390	
391	  const rl = checkRateLimit(`freemc:preset:${user.id}`, { max: 10, windowMs: 60_000 });
392	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
393	
394	  try {
395	    const host = await freemcHost();
396	
397	    // ALWAYS fully recreate the container, for every preset switch —
398	    // properties-only presets included. A `docker restart` cannot change a
399	    // container's `-e` env vars; they're fixed for that container's whole
400	    // life. A prior version of this code special-cased properties-only
401	    // presets to just delete /data/plugins and `docker restart`, on the
402	    // theory that was enough to "turn off" a previous plugins-based preset.
403	    // It wasn't: if a plugins preset (SkyBlock etc.) was EVER applied,
404	    // MODRINTH_PROJECTS/TYPE=PAPER/VERSION stayed baked into the container
405	    // forever, so deleting the jars and restarting just made itzg's
406	    // entrypoint see them missing and REDOWNLOAD + reinstall the exact same
407	    // plugin set from the still-present env var — "switching back to
408	    // Vanilla" silently kept running the old plugin preset indefinitely.
409	    // Confirmed live: SkyBlock's plugins re-enabling in the container logs
410	    // after the DB had already recorded a switch to "vanilla", which is
411	    // exactly why that account's server stopped being reachable no matter
412	    // which preset it was set to. Recreating every time is the only version
413	    // of this that's correct in every case — `docker run -d` returns the
414	    // instant the container STARTS, not once its entrypoint actually
415	    // succeeds, so this always verifies the container is still running a
416	    // few seconds later and rolls back to the account's PREVIOUS preset if
417	    // the new one's install turns out broken, rather than leaving the
418	    // customer with a dead container.
419	    const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
420	    const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);
421	    const previous = FREEMC_PRESETS[row.preset] ?? FREEMC_PRESETS.vanilla;
422	
423	    const outcome = await withServerSsh(host, async (conn) => {
424	      await exec(conn, `docker exec ${shellQuote(row.containerName)} sh -c 'rm -rf /data/plugins/*'`, 15_000).catch(() => {});
425	      const applied = await recreatePresetContainer(conn, row, preset, user.id, domain, ramMb);
426	      if (applied.ok) return { ok: true as const };
427	
428	      console.error("[free-minecraft] preset boot failed, rolling back:", applied.error);
429	      const rolledBack = await recreatePresetContainer(conn, row, previous, user.id, domain, ramMb);
430	      return rolledBack.ok
431	        ? { ok: false as const, error: "That preset didn't start cleanly, so we put your server back the way it was." }
432	        : { ok: false as const, error: "That preset didn't start, and restoring your previous setup also failed — please contact support." };
433	    });
434	    if (!outcome.ok) return { error: outcome.error };
435	  } catch (e) {
436	    console.error("[free-minecraft] preset apply failed:", e);
437	    return { error: "Couldn't apply that preset — please try again." };
438	  }
439	  await db.freeMinecraftServer.update({ where: { id: row.id }, data: { preset: presetKey } });
440	  revalidatePath("/dashboard/free-minecraft");
441	  return {};
442	}
443	
444	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
445	
446	/** Recreates the free server's container for `preset` and verifies it's
447	 *  still alive ~15s later (long enough for an init-time plugin/version
448	 *  failure to have already killed it — a normal boot takes 60s+ and would
449	 *  never trip this). Never throws; the caller decides what a failure means. */
450	async function recreatePresetContainer(
451	  conn: import("ssh2").Client,
452	  row: { id: string; containerName: string; subdomain: string },
453	  preset: (typeof FREEMC_PRESETS)[string],
454	  userId: string,
455	  domain: string,
456	  ramMb: number,
457	): Promise<{ ok: boolean; error?: string }> {
458	  const jvmRatio = preset.kind === "plugins" ? 0.7 : 0.85; // plugins need more non-heap headroom (Netty, plugin state, extra dimensions) — an 85% split OOM-killed a real plugin preset in testing
459	  const jvmMb = Math.max(256, Math.round(ramMb * jvmRatio));
460	  const envVars = preset.kind === "plugins" ? { ...propertiesToEnv(preset.properties), ...(preset.env ?? {}) } : {};
461	  const envFlags = Object.entries(envVars)
462	    .map(([k, v]) => `-e ${k}=${shellQuote(v)}`)
463	    .join(" ");
464	  // mc-router's Docker wake-from-sleep path has a HARDCODED 60s reachability
465	  // timeout with no config flag to raise it (confirmed against its source —
466	  // see server/docker.go's makeWakerFunc). A plugin preset booting >60s (e.g.
467	  // SkyBlock: EssentialsX + LuckPerms + IridiumSkyblock + 3 dimensions) means
468	  // the router gives up and the customer sees "Failed to connect / Timed out"
