/**
 * One-off LIVE verification script for the freemc-worlds task — NOT part of
 * the shipped feature, deleted before finishing. Boots real test containers
 * on freemc-host to confirm itzg's LEVEL env var actually isolates world
 * folders the way the task spec assumes, before any product code is written
 * against that assumption.
 */
import { db } from "./lib/db";
import { withServerSsh, exec, shellQuote } from "./lib/ssh-exec";
import type { SftpServer } from "./lib/sftp";

async function freemcHost(): Promise<SftpServer> {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
  });
  if (!host) throw new Error("freemc-host not found");
  return host;
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function main() {
  const host = await freemcHost();
  const dataDir = "/opt/freemc/servers/__worldtest__";
  const containerA = "mc-worldtest-a";
  const containerB = "mc-worldtest-b";
  const containerPlugin = "mc-worldtest-plugin";

  await withServerSsh(host, async (conn) => {
    console.log("== cleanup any stale test state ==");
    await exec(conn, `docker rm -f ${shellQuote(containerA)} ${shellQuote(containerB)} ${shellQuote(containerPlugin)}`, 30_000).catch(() => {});
    await exec(conn, `rm -rf ${shellQuote(dataDir)}`, 15_000);
    await exec(conn, `mkdir -p ${shellQuote(dataDir)}`, 15_000);

    console.log("\n== TEST 1: two vanilla containers, same volume, different LEVEL ==");
    const runA = await exec(
      conn,
      [
        "docker run -d",
        `--name ${shellQuote(containerA)}`,
        "--network freemc",
        "--memory=1024m --memory-swap=1024m --cpus=1",
        `-v ${shellQuote(dataDir)}:/data`,
        "-e EULA=TRUE -e TYPE=VANILLA -e ONLINE_MODE=FALSE -e MEMORY=768m",
        "-e LEVEL=testmodeA",
        "itzg/minecraft-server",
      ].join(" "),
      60_000,
    );
    console.log("runA code:", runA.code, runA.stderr.slice(0, 300));

    // Wait for world generation (vanilla, small, should be quick) then stop
    // before starting B, since both would otherwise fight over the RCON/game
    // port on the same docker network (not relevant to LEVEL, just avoids
    // port clashes clouding the result).
    console.log("waiting 45s for container A to generate its world...");
    await sleep(45_000);
    const lsAfterA = await exec(conn, `ls -la ${shellQuote(dataDir)}`, 15_000);
    console.log("ls /data after A boot:\n", lsAfterA.stdout);
    await exec(conn, `docker rm -f ${shellQuote(containerA)}`, 30_000);

    const runB = await exec(
      conn,
      [
        "docker run -d",
        `--name ${shellQuote(containerB)}`,
        "--network freemc",
        "--memory=1024m --memory-swap=1024m --cpus=1",
        `-v ${shellQuote(dataDir)}:/data`,
        "-e EULA=TRUE -e TYPE=VANILLA -e ONLINE_MODE=FALSE -e MEMORY=768m",
        "-e LEVEL=testmodeB",
        "itzg/minecraft-server",
      ].join(" "),
      60_000,
    );
    console.log("runB code:", runB.code, runB.stderr.slice(0, 300));
    console.log("waiting 45s for container B to generate its world...");
    await sleep(45_000);
    const lsAfterB = await exec(conn, `ls -la ${shellQuote(dataDir)}`, 15_000);
    console.log("ls /data after B boot (A's folders should be untouched):\n", lsAfterB.stdout);
    await exec(conn, `docker rm -f ${shellQuote(containerB)}`, 30_000);

    console.log("\n== TEST 2: Paper + IridiumSkyblock plugin container with LEVEL=skyblock ==");
    const runPlugin = await exec(
      conn,
      [
        "docker run -d",
        `--name ${shellQuote(containerPlugin)}`,
        "--network freemc",
        "--memory=1536m --memory-swap=1536m --cpus=2",
        `-v ${shellQuote(dataDir)}:/data`,
        "-e EULA=TRUE -e TYPE=PAPER -e ONLINE_MODE=FALSE -e MEMORY=1024m -e VERSION=26.1.2",
        "-e LEVEL=skyblock",
        "-e MODRINTH_PROJECTS=iridiumskyblock,vaultunlocked,essentialsx,luckperms,worldedit",
        "itzg/minecraft-server",
      ].join(" "),
      90_000,
    );
    console.log("runPlugin code:", runPlugin.code, runPlugin.stderr.slice(0, 300));
    console.log("waiting 75s for Paper + plugins to boot and generate islands...");
    await sleep(75_000);
    const lsAfterPlugin = await exec(conn, `ls -la ${shellQuote(dataDir)}`, 15_000);
    console.log("ls /data after plugin boot:\n", lsAfterPlugin.stdout);
    const inspectRunning = await exec(conn, `docker inspect -f '{{.State.Running}}' ${shellQuote(containerPlugin)}`, 10_000);
    console.log("plugin container still running:", inspectRunning.stdout.trim());
    const logs = await exec(conn, `docker logs --tail 40 ${shellQuote(containerPlugin)}`, 15_000);
    console.log("last 40 log lines:\n", logs.stdout, logs.stderr);

    console.log("\n== cleanup ==");
    await exec(conn, `docker rm -f ${shellQuote(containerA)} ${shellQuote(containerB)} ${shellQuote(containerPlugin)}`, 30_000).catch(() => {});
    await exec(conn, `rm -rf ${shellQuote(dataDir)}`, 15_000);
    console.log("done.");
  });
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error("FATAL:", e);
    process.exit(1);
  });

