/**
 * Second one-off LIVE verification script — confirms that a MODE change
 * (RCON + restart, same container/LEVEL) never disturbs a TYPE's world data,
 * and that a TYPE switch away-and-back preserves both the world data AND
 * correctly re-applies whatever mode was active. Deleted before finishing.
 */
import { db } from "./lib/db";
import { withServerSsh, exec, shellQuote } from "./lib/ssh-exec";
import type { SftpServer } from "./lib/sftp";
import { rconPasswordFor, sendRcon } from "./lib/free-minecraft-control";

async function freemcHost(): Promise<SftpServer> {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
  });
  if (!host) throw new Error("freemc-host not found");
  return host;
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const OWNER = "worldtest-owner";
const PW = rconPasswordFor(OWNER);
const dataDir = "/opt/freemc/servers/__worldtest3__";
const container = "mc-worldtest3";

function runCmd(level: string, mode: string, difficulty: string) {
  return [
    "docker run -d",
    `--name ${shellQuote(container)}`,
    "--network freemc",
    "--memory=1024m --memory-swap=1024m --cpus=1",
    `-v ${shellQuote(dataDir)}:/data`,
    "-e EULA=TRUE -e TYPE=VANILLA -e ONLINE_MODE=FALSE -e MEMORY=768m",
    `-e LEVEL=${shellQuote(level)}`,
    `-e MODE=${shellQuote(mode)} -e DIFFICULTY=${shellQuote(difficulty)}`,
    `-e ENABLE_RCON=true -e RCON_PASSWORD=${shellQuote(PW)}`,
    "itzg/minecraft-server",
  ].join(" ");
}

async function main() {
  const host = await freemcHost();
  await withServerSsh(host, async (conn) => {
    console.log("== cleanup ==");
    await exec(conn, `docker rm -f ${shellQuote(container)}`, 30_000).catch(() => {});
    await exec(conn, `rm -rf ${shellQuote(dataDir)}`, 15_000);
    await exec(conn, `mkdir -p ${shellQuote(dataDir)}`, 15_000);

    console.log("\n== STEP 1: boot LEVEL=typeX MODE=creative ==");
    const run1 = await exec(conn, runCmd("typeX", "creative", "peaceful"), 60_000);
    console.log("run1 code:", run1.code, run1.stderr.slice(0, 200));
    await sleep(35_000);
    const rcon1 = await sendRcon(conn, container, OWNER, "gamerule keepInventory true");
    console.log("set gamerule keepInventory=true on typeX:", rcon1);
    const props1 = await exec(conn, `docker exec ${shellQuote(container)} sh -c 'grep -E "^(gamemode|difficulty)=" /data/server.properties'`, 10_000);
    console.log("server.properties after step1:", props1.stdout);
    const regionList1 = await exec(conn, `docker exec ${shellQuote(container)} sh -c 'ls /data/typeX/region | head -3'`, 10_000);
    console.log("typeX region files:", regionList1.stdout);

    console.log("\n== STEP 2: MODE switch to survival — RCON + restart, SAME container, NOT recreate ==");
    // Write new properties + restart, exactly like applyFreeMinecraftGameMode will.
    const write2 = await exec(
      conn,
      `docker exec ${shellQuote(container)} sh -c "sed -i 's/^gamemode=.*/gamemode=survival/; s/^difficulty=.*/difficulty=normal/; s/^hardcore=.*/hardcore=false/' /data/server.properties"`,
      10_000,
    );
    console.log("sed exit:", write2.code, write2.stderr);
    const restart2 = await exec(conn, `docker restart ${shellQuote(container)}`, 30_000);
    console.log("restart exit:", restart2.code);
    await sleep(20_000);
    const props2 = await exec(conn, `docker exec ${shellQuote(container)} sh -c 'grep -E "^(gamemode|difficulty)=" /data/server.properties'`, 10_000);
    console.log("server.properties after mode switch:", props2.stdout);
    const rcon2 = await sendRcon(conn, container, OWNER, "gamerule keepInventory");
    console.log("gamerule keepInventory after mode switch (should still be true — same world):", rcon2);
    const lsAfterModeSwitch = await exec(conn, `docker exec ${shellQuote(container)} sh -c 'ls /data | grep typeX'`, 10_000);
