// =============================================================================
// GAME TYPE / GAME MODE — the two-axis model (2026-08-25)
// =============================================================================
// FREEMC_PRESETS above is the OLD flat 12-option model, kept ONLY because the
// pre-existing dashboard UI (components/customer/freemc/*.tsx, off-limits to
// this change — a parallel change is replacing it) still reads it directly.
// Every new call site should use FREEMC_GAME_TYPES + FREEMC_GAME_MODES below
// instead. Do not add anything new to FREEMC_PRESETS.
//
// GAME TYPE = which world/game-experience (vanilla, skyblock, prison, ...).
// Each one gets its own ISOLATED, persistent world — switching types never
// touches another type's saved world again. Mechanically: every type maps to
// its own itzg `LEVEL` value (the sanitized type key itself), so its world
// lives in its own `<LEVEL>`/`<LEVEL>_nether`/`<LEVEL>_the_end` folder set
// inside the SAME /data volume mount (see recreateForGameType in
// lib/actions-freemc-worlds.ts). This directly fixes the production incident
// where a SkyBlock->Vanilla switch corrupted the one shared world.
//
// GAME MODE = survival/hardcore/creative/peaceful, a lightweight
// server.properties overlay (gamemode/hardcore/difficulty) applied WITHIN
// whichever type is currently active, via RCON + a restart of the SAME
// container — no world switch, no recreate, no LEVEL change.
//
// LEVEL behavior confirmed LIVE against freemc-host before writing any of the
// code that depends on it (2026-08-25):
//   - Two containers on the SAME /data volume, `-e LEVEL=testmodeA` and
//     `-e LEVEL=testmodeB`, each produced their own `<LEVEL>`/`<LEVEL>_nether`/
//     `<LEVEL>_the_end` folder set; neither boot touched the other's files.
//   - A Paper container with `-e LEVEL=skyblock` created `skyblock`/
//     `skyblock_nether`/`skyblock_the_end` as its BASE world (confirmed via
//     `ServerLevel[skyblock]` in the boot log), exactly like the vanilla case.
//   - HOWEVER: IridiumSkyblock's own custom dimensions do NOT follow LEVEL —
//     they are always named `iridiumskyblock`/`iridiumskyblock_nether`/
//     `iridiumskyblock_the_end` regardless of the LEVEL value (the plugin
//     hardcodes its own world name). That's harmless for isolation ACROSS
//     accounts (every account has its own /data volume) and across OTHER game
//     types on the same account (no other type here uses IridiumSkyblock), but
//     it means deleteFreeMinecraftWorld must remove these explicitly too, not
//     just glob `<LEVEL>*` — see `extraWorldFolders` below.
//   - Restarting the SAME container (a MODE change) never touched any world
//     folder other than normal in-place saves; recreating with the SAME LEVEL
//     again reloaded the existing world (confirmed via a gamerule set before
//     the round-trip still reading back true after switching away to a
//     different type and back) rather than regenerating it.

const GAME_TYPE_KEYS = [
  "vanilla",
  "skyblock",
  "prison",
  "towny",
  "parkour",
  "anarchy",
  "lifesteal",
  "missilewars",
  "survivalgames",
] as const;

export type FreeMcGameType = FreeMcPreset & {
  /** Extra plugin-created dimension folder names that do NOT follow the
   *  LEVEL-based naming scheme (see the confirmation note above) — a world
   *  delete must remove these explicitly too, or it leaves orphaned plugin
   *  data behind under a folder name that looks unrelated to the type. */
  extraWorldFolders?: string[];
};

function buildGameType(key: (typeof GAME_TYPE_KEYS)[number]): FreeMcGameType {
  const base = FREEMC_PRESETS[key];
  if (key === "skyblock") {
    return { ...base, extraWorldFolders: ["iridiumskyblock", "iridiumskyblock_nether", "iridiumskyblock_the_end"] };
  }
  return { ...base };
}

/** The 9 GAME TYPES. Deliberately derived from FREEMC_PRESETS rather than
 *  redeclared, so label/description/kind/type/env/setupNote/heroImage can
 *  never drift between the old and new maps — the only difference here is
 *  dropping the 3 mode-only legacy entries (creative/hardcore/peaceful, now
 *  FREEMC_GAME_MODES) and attaching extraWorldFolders where a plugin needs it. */
export const FREEMC_GAME_TYPES: Record<string, FreeMcGameType> = Object.fromEntries(
  GAME_TYPE_KEYS.map((key) => [key, buildGameType(key)]),
) as Record<string, FreeMcGameType>;

export type FreeMcGameMode = {
  label: string;
  description: string;
  /** Always exactly these 3 server.properties keys — a mode is a lightweight
   *  overlay, not a full config; anything else (pvp, spawn-protection, ...) is
   *  the active game TYPE's own concern. */
  properties: { gamemode: string; hardcore: string; difficulty: string };
};

export const FREEMC_GAME_MODES: Record<string, FreeMcGameMode> = {
  survival: {
    label: "Survival",
    description: "The default experience — normal difficulty, mobs and hunger on.",
    properties: { gamemode: "survival", hardcore: "false", difficulty: "normal" },
  },
  hardcore: {
    label: "Hardcore",
    description: "One life — you're banned from the world on death.",
    properties: { gamemode: "survival", hardcore: "true", difficulty: "hard" },
  },
  creative: {
    label: "Creative",
    description: "Everyone can fly and build with unlimited blocks.",
    properties: { gamemode: "creative", hardcore: "false", difficulty: "peaceful" },
  },
  peaceful: {
    label: "Peaceful",
    description: "No hostile mobs, just building and exploring.",
    properties: { gamemode: "survival", hardcore: "false", difficulty: "peaceful" },
  },
};

/** Merges a game type's own base properties with the active game mode's
 *  overlay — mode wins on the 3 keys it controls (gamemode/hardcore/
 *  difficulty); everything else the type declares (pvp, spawn-protection,
 *  view-distance, ...) passes through untouched. This is the single function
 *  every container boot/restart for the two-axis model computes its final
 *  server.properties/env from, so a type switch can never silently lose
 *  whatever mode was active, and a mode switch can never touch anything the
 *  type itself owns. */
export function mergeGameTypeAndMode(
  type: FreeMcGameType,
  mode: FreeMcGameMode,
): Record<string, string> {
  return { ...type.properties, ...mode.properties };
}

