export function mergeGameTypeAndMode(
  type: FreeMcGameType,
  mode: FreeMcGameMode,
): Record<string, string> {
  return { ...type.properties, ...mode.properties };
}

/** The 3 keys a GAME MODE controls — see the big verification note above:
 *  confirmed LIVE that these must NEVER be baked as container env vars
 *  (-e MODE=/-e DIFFICULTY=/-e HARDCORE=), because itzg's entrypoint
 *  re-derives server.properties from them on EVERY container start,
 *  including a plain `docker restart` — which would silently discard a
 *  mode-only restart's server.properties edit right back to whatever was
 *  baked in at the last recreate. They're always applied by writing
 *  server.properties directly instead (applyModeProperties below). */
const MODE_CONTROLLED_KEYS = new Set(["gamemode", "hardcore", "difficulty"]);

/** Env vars to pass at container-CREATE time for a game type — everything
 *  the type declares (pvp, motd, spawn-protection, ...) EXCEPT the 3
 *  mode-controlled keys, which are deliberately left out (see
 *  MODE_CONTROLLED_KEYS) so a later mode-only restart can always change them
 *  cleanly. Only kind:"plugins" types env-bake anything at all — a
 *  kind:"properties" type (just vanilla, in the new model) has never needed
 *  env vars, same as before this change. */
export function envForGameType(type: FreeMcGameType): Record<string, string> {
  if (type.kind !== "plugins") return {};
  const nonModeProps = Object.fromEntries(
    Object.entries(type.properties).filter(([k]) => !MODE_CONTROLLED_KEYS.has(k)),
  );
  return { ...propertiesToEnv(nonModeProps), ...(type.env ?? {}) };
}

/**
 * Applies a game mode's 3 properties (gamemode/hardcore/difficulty) to the
 * CURRENTLY RUNNING container — RCON for whatever has a live command
 * (liveRconCommandFor), then a server.properties write + restart so it
 * survives and applies to everyone, exactly like applyFreeMinecraftSettings
 * already does for the general settings tab. Never recreates, never touches
 * LEVEL or any other world/env config — this is the ONLY function allowed to
 * run as part of a "mode switch, same type, same world" operation.
 */
export async function applyModeProperties(
  conn: Client,
  containerName: string,
  ownerId: string,
  mode: FreeMcGameMode,
): Promise<{ ok: boolean; error?: string }> {
  for (const [k, v] of Object.entries(mode.properties)) {
    const liveCmd = liveRconCommandFor(k, v);
    if (liveCmd) await sendRcon(conn, containerName, ownerId, liveCmd).catch(() => {});
  }
  const write = await writeServerProperties(conn, containerName, mode.properties);
  if (!write.ok) return { ok: false, error: write.error || "Could not write server.properties." };
  const restart = await exec(conn, `docker restart ${shellQuote(containerName)}`, 30_000);
  if (restart.code !== 0) return { ok: false, error: restart.stderr || "docker restart failed" };
  return { ok: true };
}

const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

/**
 * Recreates a free server's container for a target GAME TYPE, with the given
 * GAME MODE applied on top (see mergeGameTypeAndMode) — the single shared
 * implementation every game-type-switching action (lib/actions-freemc-worlds.ts,
 * lib/actions-freemc-mods.ts) builds its `docker run` from, so the LEVEL /
 * mode-controlled-key handling below can't drift between call sites the way
 * three independently hand-rolled `docker run` commands eventually would.
 *
 * Sets `-e LEVEL=<gameTypeKey>` so this type's world lives in its own
 * `<LEVEL>`/`<LEVEL>_nether`/`<LEVEL>_the_end` folder set inside the SAME
 * /data volume mount, never touching another type's saved world (confirmed
 * live — see the module-doc note above FREEMC_GAME_TYPES). Deliberately does
 * NOT env-bake gamemode/hardcore/difficulty (see envForGameType) — those are
 * applied in a second pass via applyModeProperties, once the container is
 * confirmed alive, so a later mode-only restart can always change them
 * cleanly without a recreate.
 *
 * Verifies liveness twice — once ~15s after `docker run` (long enough for an
 * init-time plugin/version failure to have already killed it), once more
 * ~8s after the follow-up mode-properties restart — and never throws; the
 * caller decides what a failure means (typically: roll back to the
 * account's previous type/mode).
 */
export async function recreateGameTypeContainer(
  conn: Client,
  params: {
    containerName: string;
    dataPath: string;
    subdomain: string;
    domain: string;
    ramMb: number;
    ownerId: string;
    gameType: FreeMcGameType;
    gameTypeKey: string;
    gameMode: FreeMcGameMode;
    /** Extra env vars layered on top of the type's own (e.g. the Mod Menu's
     *  merged MODRINTH_PROJECTS list) — last-write-wins over the type's env. */
    extraEnv?: Record<string, string>;
  },
): Promise<{ ok: boolean; error?: string }> {
  const jvmRatio = params.gameType.kind === "plugins" ? 0.7 : 0.85; // plugins need more non-heap headroom — see FREEMC_PLUGIN_MC_VERSION's neighboring history
  const jvmMb = Math.max(256, Math.round(params.ramMb * jvmRatio));
  const cpus = params.gameType.kind === "plugins" ? 2 : 1; // see recreatePresetContainer's note on mc-router's fixed 60s wake timeout

  const envVars = { ...envForGameType(params.gameType), ...(params.extraEnv ?? {}), LEVEL: params.gameTypeKey };
  const envFlags = Object.entries(envVars)
    .map(([k, v]) => `-e ${k}=${shellQuote(v)}`)
    .join(" ");

  await exec(conn, `docker rm -f ${shellQuote(params.containerName)}`, 30_000);
  const cmd = [
    "docker run -d",
    `--name ${shellQuote(params.containerName)}`,
    "--network freemc",
    `--memory=${params.ramMb}m --memory-swap=${params.ramMb}m --cpus=${cpus}`,
    `--label mc-router.host=${shellQuote(`${params.subdomain}.${params.domain}`)}`,
    `-v ${shellQuote(params.dataPath)}:/data`,
    `-e EULA=TRUE -e TYPE=${params.gameType.type ?? "VANILLA"} -e ONLINE_MODE=FALSE`,
    params.gameType.kind === "plugins" ? `-e VERSION=${shellQuote(FREEMC_PLUGIN_MC_VERSION)}` : "",
    `-e MEMORY=${jvmMb}m`,
    `-e ENABLE_RCON=true -e RCON_PASSWORD=${shellQuote(rconPasswordFor(params.ownerId))}`,
    envFlags,
    "itzg/minecraft-server",
  ].join(" ");
  const run = await exec(conn, cmd, 90_000); // plugin downloads can take longer than a plain boot
  if (run.code !== 0) return { ok: false, error: run.stderr || "docker run failed" };

  await sleep(15_000);
  const check = await exec(conn, `docker inspect -f '{{.State.Running}}' ${shellQuote(params.containerName)}`, 10_000);
  if (check.code !== 0 || check.stdout.trim() !== "true") {
    return { ok: false, error: "Container exited shortly after starting." };
  }

  const modeApplied = await applyModeProperties(conn, params.containerName, params.ownerId, params.gameMode);
  if (!modeApplied.ok) return { ok: false, error: modeApplied.error || "Could not apply the active game mode." };

  await sleep(8_000);
  const check2 = await exec(conn, `docker inspect -f '{{.State.Running}}' ${shellQuote(params.containerName)}`, 10_000);
  if (check2.code !== 0 || check2.stdout.trim() !== "true") {
    return { ok: false, error: "Container exited after applying the active game mode." };
  }
  return { ok: true };
}

