"use server";

/**
 * The two-axis free-Minecraft model: GAME TYPE (which isolated, persistent
 * world — vanilla/skyblock/prison/...) and GAME MODE (survival/hardcore/
 * creative/peaceful, a lightweight properties overlay applied WITHIN
 * whichever type is active). See lib/free-minecraft-control.ts's big
 * module-doc comment above FREEMC_GAME_TYPES for the full architecture note,
 * including the live LEVEL-isolation verification this is built on.
 *
 * Deliberately a separate file/module from lib/actions-free-minecraft.ts,
 * matching the file-isolation convention already established by
 * lib/actions-freemc-mods.ts and lib/actions-freemc-roles.ts in this same
 * feature area — freemcHost() below is a deliberate, identical duplicate of
 * that file's private helper (not exported there) rather than a cross-file
 * import.
 *
 * lib/actions-free-minecraft.ts's applyFreeMinecraftPreset is kept alive as a
 * DEPRECATED, backward-compatible entry point for the not-yet-migrated
 * dashboard UI (components/customer/freemc/*.tsx) — it now delegates to the
 * exact same recreateGameTypeContainer/applyModeProperties machinery this
 * file uses, so a world switched from either surface is isolated identically.
 * New UI should call the two exports below instead.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { getSetting, getSettingInt } from "./settings";
import { withServerSsh, exec, shellQuote } from "./ssh-exec";
import type { SftpServer } from "./sftp";
import {
  FREEMC_GAME_TYPES,
  FREEMC_GAME_MODES,
  legacyPresetKeyFor,
  recreateGameTypeContainer,
  applyModeProperties,
} from "./free-minecraft-control";

type Result = { error?: string };

/** Same target as lib/actions-free-minecraft.ts's freemcHost() — that helper
 *  isn't exported, so this is a deliberate, identical duplicate rather than a
 *  cross-file import, matching the file-isolation convention already used by
 *  lib/actions-freemc-mods.ts. */
async function freemcHost(): Promise<SftpServer> {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
  });
  if (!host) throw new Error("Free Minecraft host is not provisioned.");
  return host;
}

/**
 * One row per game type the caller's account has ever actually applied — a
 * world only "exists" once that type has been switched to at least once, so
 * a brand-new or not-yet-migrated account can legitimately show an empty
 * list (see the schema note on FreeMinecraftServer.activeGameType: existing,
 * already-deployed rows default to "vanilla" but won't have a
 * FreeMinecraftWorld row until they're actually switched to through this
 * file or through the legacy applyFreeMinecraftPreset).
 */
export async function listFreeMinecraftWorlds(): Promise<
  | { ok: true; worlds: { gameType: string; label: string; lastPlayedAt: string | null; isActive: boolean }[] }
  | { ok: false; error: string }
> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { ok: false, error: "You don't have a free server." };

  const worlds = await db.freeMinecraftWorld.findMany({
    where: { serverId: row.id },
    orderBy: { lastPlayedAt: "desc" },
  });

  return {
    ok: true,
    worlds: worlds.map((w) => ({
      gameType: w.gameType,
      label: w.label || FREEMC_GAME_TYPES[w.gameType]?.label || w.gameType,
      lastPlayedAt: w.lastPlayedAt ? w.lastPlayedAt.toISOString() : null,
      isActive: w.gameType === row.activeGameType,
    })),
  };
}

/**
 * Switches which GAME TYPE (isolated world) is loaded — a full container
 * recreate with the target type's `-e LEVEL=<gameType>`, same rollback-on-
 * failure discipline as the old flat-preset code (see
 * lib/actions-free-minecraft.ts's applyFreeMinecraftPreset for the incident
 * history that discipline exists to prevent). Preserves whatever GAME MODE
 * is currently active — a type switch must never silently reset the mode
 * (confirmed live, see free-minecraft-control.ts). Lazily creates the
 * FreeMinecraftWorld row on a type's first-ever visit; every other type is
 * simply never touched.
 */
export async function switchFreeMinecraftGameType(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const gameType = String(formData.get("gameType") ?? "");
  const targetType = FREEMC_GAME_TYPES[gameType];
  if (!targetType) return { error: "Unknown game type." };

  const rl = checkRateLimit(`freemc:gametype:${user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  const activeMode = FREEMC_GAME_MODES[row.activeGameMode] ?? FREEMC_GAME_MODES.survival;
  const now = new Date();

  if (gameType === row.activeGameType) {
    // Already here — just a re-visit, not a real switch. Touch the world's
    // lastPlayedAt (creating the row if this is somehow the first time it's
    // been recorded) without going anywhere near the container.
    await db.freeMinecraftWorld.upsert({
      where: { serverId_gameType: { serverId: row.id, gameType } },
      update: { lastPlayedAt: now },
      create: { serverId: row.id, gameType, label: targetType.label, lastPlayedAt: now },
    });
    revalidatePath("/dashboard/free-minecraft");
    return {};
  }

  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);
  const previousTypeKey = FREEMC_GAME_TYPES[row.activeGameType] ? row.activeGameType : "vanilla";
  const previousType = FREEMC_GAME_TYPES[previousTypeKey];

  try {
    const host = await freemcHost();
    const outcome = await withServerSsh(host, async (conn) => {
      // Same reasoning as the legacy preset switch: plugin jars from the
      // PREVIOUS type must be cleared, or itzg's entrypoint syncs the new
      // type's env against a plugins/ dir still full of the old type's jars.
      await exec(conn, `docker exec ${shellQuote(row.containerName)} sh -c 'rm -rf /data/plugins/*'`, 15_000).catch(() => {});
      const applied = await recreateGameTypeContainer(conn, {
        containerName: row.containerName,
        dataPath: `/opt/freemc/servers/${row.id}`,
        subdomain: row.subdomain,
        domain,
        ramMb,
        ownerId: user.id,
        gameType: targetType,
        gameTypeKey: gameType,
        gameMode: activeMode,
      });
      if (applied.ok) return { ok: true as const };

      console.error("[freemc-worlds] game type switch failed, rolling back:", applied.error);
      const rolledBack = await recreateGameTypeContainer(conn, {
        containerName: row.containerName,
        dataPath: `/opt/freemc/servers/${row.id}`,
        subdomain: row.subdomain,
        domain,
        ramMb,
        ownerId: user.id,
        gameType: previousType,
        gameTypeKey: previousTypeKey,
        gameMode: activeMode,
      });
      return rolledBack.ok
        ? { ok: false as const, error: "That game type didn't start cleanly, so we put your server back the way it was." }
        : { ok: false as const, error: "That game type didn't start, and restoring your previous one also failed — please contact support." };
    });
    if (!outcome.ok) return { error: outcome.error };
  } catch (e) {
    console.error("[freemc-worlds] switch game type failed:", e);
    return { error: "Couldn't switch game type — please try again." };
  }

  await db.freeMinecraftServer.update({
    where: { id: row.id },
    data: { activeGameType: gameType, preset: legacyPresetKeyFor(gameType, row.activeGameMode) },
  });
  await db.freeMinecraftWorld.upsert({
    where: { serverId_gameType: { serverId: row.id, gameType } },
    update: { lastPlayedAt: now },
    create: { serverId: row.id, gameType, label: targetType.label, lastPlayedAt: now },
  });
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

/**
 * Applies a GAME MODE overlay (gamemode/hardcore/difficulty) to whichever
 * world is currently active — RCON + a restart of the SAME container, never
 * a recreate, never touches LEVEL or any other world's data. See
 * free-minecraft-control.ts's applyModeProperties for why the 3 properties
 * this touches are deliberately never baked as container env vars (confirmed
 * live: they'd get silently reasserted on every restart otherwise, which
 * would break exactly this action).
 */
export async function applyFreeMinecraftGameMode(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const gameMode = String(formData.get("gameMode") ?? "");
  const mode = FREEMC_GAME_MODES[gameMode];
  if (!mode) return { error: "Unknown game mode." };

  const rl = checkRateLimit(`freemc:gamemode:${user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  if (gameMode === row.activeGameMode) return {};

  try {
    const host = await freemcHost();
    await withServerSsh(host, async (conn) => {
      const applied = await applyModeProperties(conn, row.containerName, user.id, mode);
      if (!applied.ok) throw new Error(applied.error || "Could not apply game mode.");
    });
  } catch (e) {
    console.error("[freemc-worlds] apply game mode failed:", e);
    return { error: "Couldn't apply that game mode — please try again." };
  }

  await db.freeMinecraftServer.update({
    where: { id: row.id },
    data: { activeGameMode: gameMode, preset: legacyPresetKeyFor(row.activeGameType, gameMode) },
  });
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

export async function renameFreeMinecraftWorld(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const gameType = String(formData.get("gameType") ?? "");
  if (!FREEMC_GAME_TYPES[gameType]) return { error: "Unknown game type." };

  const label = String(formData.get("label") ?? "").trim().slice(0, 40);
  if (!label) return { error: "Enter a name." };

  // db.freeMinecraftWorld.update({where:{serverId_gameType:...}}) IS the
  // ownership check here, same pattern as every other free-Minecraft action:
  // a world row can only ever be found under the caller's own server.
  try {
    await db.freeMinecraftWorld.update({
      where: { serverId_gameType: { serverId: row.id, gameType } },
      data: { label },
    });
  } catch {
    return { error: "That world doesn't exist yet — switch to it first." };
  }
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

/**
 * Deletes one game type's saved world — refuses if it's the currently-active
 * type (switch away first, or the container would be pointed at a world that
 * no longer exists). Removes exactly `<gameType>`, `<gameType>_nether`,
 * `<gameType>_the_end`, plus any plugin-specific custom dimension folders
 * that don't follow the LEVEL-based naming scheme (see
 * FreeMcGameType.extraWorldFolders — confirmed live that IridiumSkyblock's
 * `iridiumskyblock*` dimensions are one such case). Every path removed is an
 * exact, individually shell-quoted folder name under this server's own data
 * dir, never a glob and never the bare data dir itself, so this can never
 * remove anything but this one type's own world data.
 */
export async function deleteFreeMinecraftWorld(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const gameType = String(formData.get("gameType") ?? "");
  const type = FREEMC_GAME_TYPES[gameType];
  if (!type) return { error: "Unknown game type." };

  if (gameType === row.activeGameType) {
    return { error: "You can't delete the world you're currently playing on — switch to a different game type first." };
  }

  const rl = checkRateLimit(`freemc:deleteworld:${user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  const world = await db.freeMinecraftWorld.findUnique({ where: { serverId_gameType: { serverId: row.id, gameType } } });
  if (!world) return { error: "That world doesn't exist." };

  try {
    const host = await freemcHost();
    const dataPath = `/opt/freemc/servers/${row.id}`;
    const folders = [gameType, `${gameType}_nether`, `${gameType}_the_end`, ...(type.extraWorldFolders ?? [])];
    await withServerSsh(host, async (conn) => {
      for (const folder of folders) {
        await exec(conn, `rm -rf ${shellQuote(`${dataPath}/${folder}`)}`, 15_000);
      }
    });
  } catch (e) {
    // Best-effort disk cleanup, same tolerance as deleteFreeMinecraftServer —
    // the DB row (what the customer actually sees) is removed regardless, so
    // a transient SSH failure never leaves a "delete" that silently no-ops.
    console.error("[freemc-worlds] world folder cleanup failed (row removed regardless):", e);
  }

  await db.freeMinecraftWorld.delete({ where: { id: world.id } });
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

input.old_string:
"use server";

/**
 * Mod Menu action: lets a free-tier Minecraft owner layer EXTRA vetted
 * plugins (lib/freemc-mod-catalog.ts) on top of whatever their active preset
 * already bundles. Follows the exact same container-recreate discipline as
 * applyFreeMinecraftPreset in lib/actions-free-minecraft.ts: docker rm -f the
 * old container, docker run -d the new one, sleep 15s, then docker inspect to
 * confirm it's still alive before trusting it — `docker run -d`'s own exit
 * code only means the process started, not that it survived an init-time
 * plugin failure. On failure this rolls back to the account's PREVIOUS
 * extraMods list rather than leaving the customer with a dead server, and
 * `extraMods` is only ever persisted on the DB row once the new container is
 * confirmed running.
 *
 * Deliberately a separate file/module from lib/actions-free-minecraft.ts (per
 * this feature's isolation requirement) rather than reusing its private
 * `recreatePresetContainer`/`freemcHost` helpers, which aren't exported — the
 * container-run command below is kept in lock-step with that function's
 * shape on purpose; if that file's recreate logic changes, this should be
 * updated to match.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { getSetting, getSettingInt } from "./settings";
import { withServerSsh, exec, shellQuote } from "./ssh-exec";
import type { SftpServer } from "./sftp";
import {
  rconPasswordFor,
  propertiesToEnv,
  FREEMC_PRESETS,
  FREEMC_PLUGIN_MC_VERSION,
  type FreeMcPreset,
} from "./free-minecraft-control";
import { FREEMC_MOD_CATALOG } from "./freemc-mod-catalog";

type Result = { error?: string };

const CATALOG_SLUGS = new Set(FREEMC_MOD_CATALOG.map((m) => m.slug));

/** Same target as lib/actions-free-minecraft.ts's freemcHost() — that helper
 *  isn't exported, so this is a deliberate, identical duplicate rather than a
 *  cross-file import, per this feature's file-isolation requirement. */
async function freemcHost(): Promise<SftpServer> {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
  });
  if (!host) throw new Error("Free Minecraft host is not provisioned.");
  return host;
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

/**
 * Recreates the free server's container for `preset`, with `extraModSlugs`
 * merged into MODRINTH_PROJECTS on top of whatever the preset itself already
 * declares, and verifies it's still alive ~15s later — identical health-check
 * timing/shape to recreatePresetContainer in lib/actions-free-minecraft.ts.
 * Never throws; the caller decides what a failure means.
 */
async function recreateWithMods(
  conn: import("ssh2").Client,
  row: { id: string; containerName: string; subdomain: string },
  preset: FreeMcPreset,
  extraModSlugs: string[],
  userId: string,
  domain: string,
  ramMb: number,
): Promise<{ ok: boolean; error?: string }> {
  const jvmRatio = 0.7; // this action only ever runs against kind:"plugins" presets
  const jvmMb = Math.max(256, Math.round(ramMb * jvmRatio));

  const baseEnv = { ...propertiesToEnv(preset.properties), ...(preset.env ?? {}) };
  const presetSlugs = (baseEnv.MODRINTH_PROJECTS ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  const mergedSlugs = [...new Set([...presetSlugs, ...extraModSlugs])];
  const envVars = { ...baseEnv, MODRINTH_PROJECTS: mergedSlugs.join(",") };

  const envFlags = Object.entries(envVars)
    .map(([k, v]) => `-e ${k}=${shellQuote(v)}`)
    .join(" ");

  await exec(conn, `docker rm -f ${shellQuote(row.containerName)}`, 30_000);
  // Clear old plugin jars first — same reasoning as applyFreeMinecraftPreset:
  // MODRINTH_PROJECTS only ADDS/updates what it lists, it never prunes a jar
  // that's no longer listed, so a mod the owner just REMOVED would otherwise
  // keep running.
  await exec(conn, `rm -rf ${shellQuote(`/opt/freemc/servers/${row.id}/plugins`)}`, 15_000).catch(() => {});
  const cmd = [
    "docker run -d",
    `--name ${shellQuote(row.containerName)}`,
    "--network freemc",
    `--memory=${ramMb}m --memory-swap=${ramMb}m --cpus=1`,
    `--label mc-router.host=${shellQuote(`${row.subdomain}.${domain}`)}`,
    `-v ${shellQuote(`/opt/freemc/servers/${row.id}`)}:/data`,
    `-e EULA=TRUE -e TYPE=${preset.type ?? "PAPER"} -e ONLINE_MODE=FALSE`,
    `-e VERSION=${shellQuote(FREEMC_PLUGIN_MC_VERSION)}`,
    `-e MEMORY=${jvmMb}m`,
    `-e ENABLE_RCON=true -e RCON_PASSWORD=${shellQuote(rconPasswordFor(userId))}`,
    envFlags,
    "itzg/minecraft-server",
  ].join(" ");
  const run = await exec(conn, cmd, 90_000);
  if (run.code !== 0) return { ok: false, error: run.stderr || "docker run failed" };

  await sleep(15_000);
  const check = await exec(conn, `docker inspect -f '{{.State.Running}}' ${shellQuote(row.containerName)}`, 10_000);
  if (check.code !== 0 || check.stdout.trim() !== "true") {
    return { ok: false, error: "Container exited shortly after starting." };
  }
  return { ok: true };
}

export async function applyFreeMinecraftMods(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const preset = FREEMC_PRESETS[row.preset];
  if (!preset || preset.kind !== "plugins") {
    return { error: "Your current game mode doesn't run plugins, so there's nothing for extra mods to install into. Switch to a plugin-based preset first." };
  }

